// And groups predicates with the AND operator between them.
func And(predicates ...predicate.LiveSafetyState) predicate.LiveSafetyState {
	return predicate.LiveSafetyState(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.LiveSafetyState) predicate.LiveSafetyState {
	return predicate.LiveSafetyState(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.LiveSafetyState) predicate.LiveSafetyState {
	return predicate.LiveSafetyState(sql.NotPredicates(p))
}
